	"com/takeda/kbaipocchatbot/i18n/i18n.properties":'# This is the resource bundle for com.takeda.kbaipocchatbot\n\n# Texts for manifest.json\n\n#XTIT: Application name\nappTitle=KB AI Chatbot\n\n#YDES: Application description\nappDescription=An SAP Fiori application.\n\n#XTIT: Main view title\ntitle=KB AI Chatbot\n\n#XBTN: Button text for creating a new chat\nnewChatButtonText=+ NEW CHAT\n\n#XTIT: Chat history section title\nchatHistoryTitle=CHAT HISTORY\n\n#XTXT: Label for selected data source\ndataSourceLabel=Data source:\n\n#XTXT: Label for selected AI model\naiModelLabel=AI Model:\n\n#XBTN: Button text for editing chat settings\neditButtonText=Edit\n\n#XTXT: Empty state text for conversation list\nconversationNoDataText=Start a conversation by sending a message.\n\n#XTXT: Label for messages sent by the user\nuserMessageRoleLabel=User\n\n#XTXT: Label for messages generated by the AI assistant\nassistantMessageRoleLabel=AI Assistant\n\n#XFLD: Placeholder text for chat input field\nchatInputPlaceholder=Ask a question about your knowledge sources\n\n#XMSG: Error shown when the chat history can\'t be loaded from the backend\nchatHistoryLoadError=Couldn\'t load the chat history. Try again later.\n\n#XMSG: Placeholder shown in the assistant message while waiting for the AI response\nassistantThinking=Thinking\\u2026\n\n#XMSG: Shown in the assistant message when the AI request fails\nassistantError=Couldn\'t get an answer from the AI. Try again.\n\n#XTIT: Title of the dialog for editing the chat\'s data source and AI model\nchatSettingsDialogTitle=Edit Chat Settings\n\n#XBTN: Button text for saving the chat settings\nsaveButtonText=Save\n\n#XBTN: Button text for closing the chat settings without saving\ncancelButtonText=Cancel\n\n#XMSG: Error shown when the data sources can\'t be loaded from the backend\ndataSourcesLoadError=Couldn\'t load the data sources. Try again later.\n',
